CLGDBMSP249.code:
DECLARE
    v_number NUMBER := 153;
    v_temp NUMBER;
    v_digit NUMBER;
    v_sum NUMBER := 0;
BEGIN
    v_temp := v_number;

    WHILE v_temp > 0 LOOP
        v_digit := MOD(v_temp, 10);
        v_sum := v_sum + (v_digit * v_digit * v_digit);
        v_temp := TRUNC(v_temp / 10);
    END LOOP;

    IF v_sum = v_number THEN
        DBMS_OUTPUT.PUT_LINE(v_number || ' is an Armstrong number.');
    ELSE
        DBMS_OUTPUT.PUT_LINE(v_number || ' is not an Armstrong number.');
    END IF;
END;
/

